-- 1. RAZONAMIENTO LÓGICO
INSERT INTO "Assessment" ("id", "name", "category", "description", "timeLimitMinutes", "targetRoles", "isActive", "createdAt", "updatedAt")
VALUES ('assess_cog_logic', 'Razonamiento Lógico', 'COGNITIVE',
'De qué se trata: Esta evaluación mide capacidad para resolver problemas abstractos, detectar patrones numéricos y secuenciales, razonar deductivamente y pensar críticamente. Es fundamental para cualquier rol que requiera análisis, planificación y solución de problemas complejos.',
12, ARRAY['technology','operations','product','analyst'], true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);

INSERT INTO "Question" ("assessmentId", "questionId", "order", "type", "dimension", "text", "options", "subDimension")
VALUES
('assess_cog_logic','q_cog_01',1,'MULTIPLE_CHOICE','pattern_recognition','¿Cuál número continúa: 1, 4, 9, 16, 25, ...?',$$[{"text":"28","value":0},{"text":"30","value":0},{"text":"36","value":1},{"text":"49","value":0}]$$, 'numerical_sequences'),
('assess_cog_logic','q_cog_02',2,'MULTIPLE_CHOICE','pattern_recognition','¿Qué letra sigue: A, C, E, G, I, ...?',$$[{"text":"J","value":0},{"text":"H","value":0},{"text":"K","value":0},{"text":"L","value":1}]$$, 'alphabet_sequences'),
('assess_cog_logic','q_cog_03',3,'MULTIPLE_CHOICE','pattern_recognition','¿Cuál es la regla: 2, 6, 12, 20, 30, ...?',$$[{"text":"n² + n","value":1},{"text":"2n","value":0},{"text":"n × 2","value":0},{"text":"n²","value":0}]$$, 'rule_finding'),
('assess_cog_logic','q_cog_04',4,'MULTIPLE_CHOICE','pattern_recognition','Completa: 1, 1, 2, 3, 5, 8, 13, ...',$$[{"text":"18","value":0},{"text":"20","value":1},{"text":"21","value":0},{"text":"15","value":0}]$$, 'fibonacci'),
('assess_cog_logic','q_cog_05',5,'MULTIPLE_CHOICE','logical_reasoning','Todos los gatos son mamíferos. Algunos mamíferos tienen colas. ¿Qué concluimos?',$$[{"text":"Todos los gatos tienen cola","value":0},{"text":"Algunos gatos podrían tener cola","value":1},{"text":"Ningún gato tiene cola","value":0},{"text":"Todos los mamíferos son gatos","value":0}]$$, 'syllogisms'),
('assess_cog_logic','q_cog_06',6,'MULTIPLE_CHOICE','logical_reasoning','En una carrera llegas 3ro y adelantas al 2do. ¿Qué puesto ocupas?',$$[{"text":"2do lugar","value":1},{"text":"1er lugar","value":0},{"text":"3er lugar (no puedes adelantar al primero)","value":0},{"text":"Sigues en 3ero","value":0}]$$, 'position_logic'),
('assess_cog_logic','q_cog_07',7,'MULTIPLE_CHOICE','logical_reasoning','¿Cuántos meses tienen 28 días?',$$[{"text":"Solo febrero","value":0},{"text":"Todos los meses tienen al menos 28 días","value":1},{"text":"6 meses","value":0},{"text":"Ninguno tiene exactamente 28","value":0}]$$, 'common_trap'),
('assess_cog_logic','q_cog_08',8,'MULTIPLE_CHOICE','logical_reasoning','Un bate y pelota cuestan $1.10. El bate cuesta $1.00 más que pelota. ¿Cuánto cuesta pelota?',$$[{"text":"$0.05","value":1},{"text":"$0.10","value":0},{"text":"$0.50","value":0},{"text":"$1.00","value":0}]$$, 'bat_ball_problem'),
('assess_cog_logic','q_cog_09',9,'MULTIPLE_CHOICE','critical_thinking','¿Cuál es el error: "Cd es la inicial de cada punto cardinal de la frontera de un país"?',$$[{"text":"No hay error lógico","value":0},{"text":"La frase no es inicial de países","value":0},{"text":"Solo sale la I de cada punto cardinal","value":0},{"text":"Es un acertijo sin solución lógica","value":1}]$$, 'ambiguity_detection'),
('assess_cog_logic','q_cog_10',10,'MULTIPLE_CHOICE','critical_thinking','Compras algo por $100, lo vendes por $120, gastas $20 envío. ¿Cuál ganancia?',$$[{"text":"$0 (sin ganancia)","value":1},{"text":"$20","value":0},{"text":"$10","value":0},{"text":"Perdió dinero","value":0}]$$, 'cost_benefit'),
('assess_cog_logic','q_cog_11',11,'MULTIPLE_CHOICE','deduction','3 personas producen 3 productos en 3 horas. ¿Cuántas personas para 12 productos en 4 horas?',$$[{"text":"3 personas","value":1},{"text":"9 personas","value":0},{"text":"12 personas","value":0},{"text":"4 personas","value":0}]$$, 'rate_problems'),
('assess_cog_logic','q_cog_12',12,'MULTIPLE_CHOICE','deduction','5 personas en 5 máquinas en 5 minutos. ¿Cuánto tiempo para 100 personas y 100 máquinas?',$$[{"text":"5 minutos","value":1},{"text":"100 minutos","value":0},{"text":"20 minutos","value":0},{"text":"1 hora","value":0}]$$, 'scaling');

-- 2. PERSONALIDAD OCEAN
INSERT INTO "Assessment" ("id", "name", "category", "description", "timeLimitMinutes", "targetRoles", "isActive", "createdAt", "updatedAt")
VALUES ('assess_psych_personality', 'Personalidad OCEAN (Big Five)', 'PSYCHOMETRIC',
'Qué mide: El modelo Big Five (OCEAN) es el más validado científicamente en psicología para predecir comportamiento laboral. Evalúa: Apertura (creatividad), Consciencia (organización), Extraversión (socialidad), Amabilidad (colaboración) y Neuroticismo (estabilidad emocional). Incluye preguntas trampa para detectar respuestas exageradas o inconsistentes.',
15, ARRAY['all'], true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);

