('assess_psych_personality','p_01',1,'LIKERT_SCALE','openness','Disfruto explorar nuevas ideas y conceptos abstractos.',$$[{"text":"Totalmente en desacuerdo","value":1},{"text":"En desacuerdo","value":2},{"text":"Neutral","value":3},{"text":"De acuerdo","value":4},{"text":"Totalmente de acuerdo","value":5}]$$, 'curiosity_about_ideas', false),
