('assess_psych_personality','p_07',7,'LIKERT_SCALE','conscientiousness','Siempre completo las tareas que empiezo, incluso si son difíciles.',$$[{"text":"Totalmente en desacuerdo","value":1},{"text":"En desacuerdo","value":2},{"text":"Neutral","value":3},{"text":"De acuerdo","value":4},{"text":"Totalmente de acuerdo","value":5}]$$, 'dutifulness', false),
