('assess_psych_personality','p_09',9,'LIKERT_SCALE','conscientiousness','Pongo mucho esfuerzo en hacer las cosas bien, revisando detalles.',$$[{"text":"Totalmente en desacuerdo","value":1},{"text":"En desacuerdo","value":2},{"text":"Neutral","value":3},{"text":"De acuerdo","value":4},{"text":"Totalmente de acuerdo","value":5}]$$, 'attention_to_detail', false),
('assess_psych_personality','p_10',10,'LIKERT_SCALE','conscientiousness','Me esfuerzo mucho para alcanzar mis metas, incluso si son difíciles.',$$[{"text":"Totalmente en desacuerdo","value":1},{"text":"En desacuerdo","value":2},{"text":"Neutral","value":3},{"text":"De acuerdo","value":4},{"text":"Totalmente de acuerdo","value":5}]$$, 'achievement_striving', false),
('assess_psych_personality','p_11',11,'LIKERT_SCALE','conscientiousness','Suelo procrastinar hasta que el plazo es inminente.',$$[{"text":"Totalmente en desacuerdo","value":5},{"text":"En desacuerdo","value":4},{"text":"Neutral","value":3},{"text":"De acuerdo","value":2},{"text":"Totalmente de acuerdo","value":1}]$$, 'procrastination', true),
