-- EXTRAVERSION (5)
('assess_psych_personality','p_13',13,'LIKERT_SCALE','extraversion','Me siento energizado cuando estoy rodeado de gente.',$$[{"text":"Totalmente en desacuerdo","value":1},{"text":"En desacuerdo","value":2},{"text":"Neutral","value":3},{"text":"De acuerdo","value":4},{"text":"Totalmente de acuerdo","value":5}]$$, 'social_energy', false),
('assess_psych_personality','p_14',14,'LIKERT_SCALE','extraversion','Prefiero actividades tranquilas y solas en lugar de eventos sociales.',$$[{"text":"Totalmente en desacuerdo","value":5},{"text":"En desacuerdo","value":4},{"text":"Neutral","value":3},{"text":"De acuerdo","value":2},{"text":"Totalmente de acuerdo","value":1}]$$, 'solitude_preference', true),
('assess_psych_personality','p_15',15,'LIKERT_SCALE','extraversion','Fácilmente me uno a conversaciones en grupos grandes.',$$[{"text":"Totalmente en desacuerdo","value":1},{"text":"En desacuerdo","value":2},{"text":"Neutral","value":3},{"text":"De acuerdo","value":4},{"text":"Totalmente de acuerdo","value":5}]$$, 'group_socializing', false),
('assess_psych_personality','p_16',16,'LIKERT_SCALE','extraversion','Soy más observador que participativo en reuniones.',$$[{"text":"Totalmente en desacuerdo","value":5},{"text":"En desacuerdo","value":4},{"text":"Neutral","value":3},{"text":"De acuerdo","value":2},{"text":"Totalmente de acuerdo","value":1}]$$, 'reserved_behavior', true),
