('assess_psych_personality','p_19',19,'LIKERT_SCALE','agreeableness','Prefiero ganar discusiones en lugar de llegar a un acuerdo.',$$[{"text":"Totalmente en desacuerdo","value":5},{"text":"En desacuerdo","value":4},{"text":"Neutral","value":3},{"text":"De acuerdo","value":2},{"text":"Totalmente de acuerdo","value":1}]$$, 'combativeness', true),
('assess_psych_personality','p_20',20,'LIKERT_SCALE','agreeableness','Ayudo a otros incluso cuando es difícil o me toma tiempo.',$$[{"text":"Totalmente en desacuerdo","value":1},{"text":"En desacuerdo","value":2},{"text":"Neutral","value":3},{"text":"De acuerdo","value":4},{"text":"Totalmente de acuerdo","value":5}]$$, 'altruism', false),
