('assess_psych_personality','p_23',23,'LIKERT_SCALE','neuroticism','Me cuesta conciliar el sueño cuando estoy preocupado.',$$[{"text":"Totalmente en desacuerdo","value":5},{"text":"En desacuerdo","value":4},{"text":"Neutral","value":3},{"text":"De acuerdo","value":2},{"text":"Totalmente de acuerdo","value":1}]$$, 'sleep_disturbance', true),
