-- 3. JUICIO SITUACIONAL SJT
INSERT INTO "Assessment" ("id", "name", "category", "description", "timeLimitMinutes", "targetRoles", "isActive", "createdAt", "updatedAt")
VALUES ('assess_behav_sjt', 'Juicio Situacional (SJT)', 'BEHAVIORAL',
'Qué mide: Evalúa cómo respondes ante situaciones laborales realistas con múltiples opciones. Mide leadership, trabajo en equipo, resolución de conflictos, ética profesional y manejo de presión. Cada opción tiene un peso diferente que refleja la efectividad de la respuesta.',
12, ARRAY['manager','operations','sales','marketing','all'], true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);

INSERT INTO "Question" ("assessmentId", "questionId", "order", "type", "dimension", "text", "scenario", "options", "subDimension")
VALUES
-- LEADERSHIP (3)
('assess_behav_sjt','sjt_01',1,'SCENARIO','leadership','Tu equipo tiene dos desarrolladores en conflicto sobre la arquitectura de un proyecto crítico. La fecha límite es en 2 semanas.','¿Qué harías?',$$[{"text":"Decides tu postura y la impones como líder","value":1},{"text":"Organizas sesión de brainstorming para que encuentren solución conjunta","value":5},{"text":"Dejas que resuelvan solos para que asuman responsabilidad","value":2},{"text":"Escalas al director de ingeniería para que decida","value":3}]$$, 'conflict_resolution'),
('assess_behav_sjt','sjt_02',2,'SCENARIO','leadership','Tu equipo no alcanza metas de rendimiento. Dos miembros clave tienen problemas de adicción.','¿Qué harías?',$$[{"text":"Confrontas directamente y los reemplazas","value":1},{"text":"Organizas reunión y aplicas políticas de rehabilitación","value":5},{"text":"Informas a la empresa para que busque ayuda profesional","value":3},{"text":"Ignoras el problema y esperas que se resuelva","value":2}]$$, 'performance_management'),
('assess_behav_sjt','sjt_03',3,'SCENARIO','leadership','Eres responsable de una fusión entre dos equipos con diferentes culturas. Uno es muy formal y el otro muy informal.','¿Qué harías?',$$[{"text":"Impones la cultura formal para mantener profesionalismo","value":1},{"text":"Identificas los mejores aspectos de ambas culturas y los integras","value":5},{"text":"Dejas que cada equipo mantenga su cultura","value":2},{"text":"Escalas al CEO para que decida la cultura","value":3}]$$, 'culture_integration'),
-- TEAMWORK (2)
('assess_behav_sjt','sjt_04',4,'SCENARIO','teamwork','Un compañero de equipo tiene problemas personales graves y su rendimiento ha bajado. El proyecto depende de su entrega.','¿Qué harías?',$$[{"text":"Organizas reunión para ofrecer apoyo y ajustar cargas","value":5},{"text":"Reportas la situación a tu manager","value":3},{"text":"Tomas sus tareas sin preguntar","value":1},{"text":"Ignoras la situación y esperas que se resuelva","value":2}]$$, 'peer_support'),
('assess_behav_sjt','sjt_05',5,'SCENARIO','teamwork','Estás en un equipo donde hay socios competitivos y poco colaboradores. Sientes que el trabajo no avanza.','¿Qué harías?',$$[{"text":"Comunicas el problema al manager y propones team building","value":5},{"text":"Tratas de ser más amable con cada uno individualmente","value":3},{"text":"Mientes a otros sobre el avance para "presionar" al equipo","value":1},{"text":"Te retiras del equipo para evitar el conflicto","value":2}]$$, 'collaboration_building'),
-- CONFLICT RESOLUTION (2)
('assess_behav_sjt','sjt_06',6,'SCENARIO','conflict_resolution','Un cliente importante está muy enojado porque un producto falló. Exige una disculpa pública.','¿Qué harías?',$$[{"text":"Concédes la disculpa inmediata sin investigar","value":1},{"text":"Investigas el problema, haces seguimiento personalizado y ofreces solución","value":5},{"text":"Rechazas la disculpa porque no fue tu culpa","value":3},{"text":"Escalas a legal para evitar responsabilidad","value":2}]$$, 'customer_management'),
('assess_behav_sjt','sjt_07',7,'SCENARIO','conflict_resolution','En una reunión, un colega ataca personalmente a otro miembro. El ambiente se vuelve hostil.','¿Qué harías?',$$[{"text":"Defiendes al atacado respondiendo con la misma intensidad","value":1},{"text":"Intervienes calmadamente para redirigir la discusión al tema profesional","value":5},{"text":"Ignoras el ataque y tomas notas","value":3},{"text":"Reportas el incidente a recursos humanos","value":2}]$$, 'de_escalation'),
-- ETHICS (2)
('assess_behav_sjt','sjt_08',8,'SCENARIO','ethics','Descubres que un compañero ha usado información confidencial de un cliente para beneficio personal. Lo sabes por segunda mano, sin prueba directa.','¿Qué harías?',$$[{"text":"Reportas al compañero si tienes evidencia","value":5},{"text":"Lo confrontas directamente para que se corrija","value":3},{"text":"Lo ignoras porque no tienes prueba directa","value":1},{"text":"Escalas sin investigación y sin evidencia","value":2}]$$, 'whistleblower'),
('assess_behav_sjt','sjt_09',9,'SCENARIO','ethics','Eres manager y un cliente te ofrece dinero para priorizar su proyecto sobre otros clientes.','¿Qué harías?',$$[{"text":"Aceptas pero lo oculto a la empresa","value":1},{"text":"Rechazas la oferta y reportas la situación","value":5},{"text":"Aceptas pero tratas a todos por igual","value":2},{"text":"No respondes al cliente pero mantienes la prioridad","value":3}]$$, 'bribery'),
-- PRESSURE (1)
('assess_behav_sjt','sjt_10',10,'SCENARIO','pressure_management','Tienes una presentación importante en 1 hora, pero un problema técnico crítico aparece y no hay laptop de respaldo.','¿Qué harías?',$$[{"text":"Cancelas la presentación y te vas","value":1},{"text":"Usas tu laptop personal y preparas versión simplificada","value":5},{"text":"Pides a alguien que te preste su equipo","value":2},{"text":"Presentas solo con tu smartphone","value":3}]$$, 'crisis_response');

-- 4. EVALUACIÓN TÉCNICA
INSERT INTO "Assessment" ("id", "name", "category", "description", "timeLimitMinutes", "targetRoles", "isActive", "createdAt", "updatedAt")
VALUES ('assess_tech_dev', 'Evaluación Técnica - Desarrollo', 'TECHNICAL',
'Qué mide: Cubre conceptos fundamentales de desarrollo de software: algoritmos y estructuras de datos, arquitectura de sistemas, bases de datos y buenas prácticas de código. No prueba lenguajes específicos sino conceptos universales que aplican a cualquier stack.',
12, ARRAY['technology','developer','engineer','analyst'], true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);

INSERT INTO "Question" ("assessmentId", "questionId", "order", "type", "dimension", "text", "options", "subDimension")
VALUES
-- ARCHITECTURE (3)
('assess_tech_dev','t_01',1,'MULTIPLE_CHOICE','architecture','¿Cuál patrón de diseño es más adecuado para crear una única instancia de una clase que gestiona recursos compartidos?',$$[{"text":"Factory","value":0},{"text":"Singleton","value":1},{"text":"Observer","value":0},{"text":"Strategy","value":0}]$$, 'design_patterns'),
('assess_tech_dev','t_02',2,'MULTIPLE_CHOICE','architecture','¿Cuál es la diferencia principal entre LEFT JOIN e INNER JOIN?',$$[{"text":"LEFT JOIN retorna todo de la tabla izquierda con NULL si hay match","value":1},{"text":"INNER JOIN retorna filas de ambas con match","value":1},{"text":"Son iguales","value":0},{"text":"LEFT JOIN es más rápido","value":0}]$$, 'joins'),
('assess_tech_dev','t_03',3,'MULTIPLE_CHOICE','architecture','¿Qué principio SOLID se aplica cuando una clase tiene una única responsabilidad?',$$[{"text":"Single Responsibility Principle (SRP)","value":1},{"text":"Open-Closed Principle","value":0},{"text":"Liskov Substitution Principle","value":0},{"text":"Interface Segregation","value":0}]$$, 'solid_principles'),
-- DATABASES (3)
('assess_tech_dev','t_04',4,'MULTIPLE_CHOICE','databases','¿Cuál es la complejidad temporal de acceder a un elemento por índice en un array?',$$[{"text":"O(1)","value":1},{"text":"O(n)","value":0},{"text":"O(log n)","value":0},{"text":"O(n²)","value":0}]$$, 'arrays'),
('assess_tech_dev','t_05',5,'MULTIPLE_CHOICE','databases','¿Qué tipo de índice es más eficiente para consultas de rango?',$$[{"text":"B-Tree (árbol balanceado)","value":1},{"text":"Hash Index","value":0},{"text":"Bitmap Index","value":0},{"text":"No hay diferencia","value":0}]$$, 'indexing'),
('assess_tech_dev','t_06',6,'MULTIPLE_CHOICE','databases','¿Cuál es la ventaja principal de MongoDB sobre SQL?',$$[{"text":"Escalabilidad horizontal flexible y esquema flexible","value":1},{"text":"Siempre más rápido","value":0},{"text":"Soporta transacciones ACID","value":0},{"text":"Más seguro","value":0}]$$, 'nosql_vs_sql'),
-- ALGORITHMS (3)
